<script>
  import { Activity, BriefcaseBusiness, Building2, GraduationCap, ArrowRight, Sparkles, Clock3, CircleCheck, CalendarDays } from 'lucide-svelte';
  import StatCard from './StatCard.svelte';
  import StatusBadge from './StatusBadge.svelte';
  let { modules = [], data = {}, role = '', onnavigate = () => {} } = $props();
  const activePractices=$derived((data.PRACTICAS||[]).filter(x=>/proceso/i.test(x.estado||'')));
  const upcoming=$derived((data.PRACTICAS||[]).filter(x=>x.fecha_fin&&new Date(x.fecha_fin)>=new Date()).sort((a,b)=>String(a.fecha_fin).localeCompare(String(b.fecha_fin))).slice(0,4));
  const sampleUpcoming = (() => {
    const today = new Date();
    today.setHours(12, 0, 0, 0);
    return [
      { days: 3, title: 'Entrega del informe de avance', context: 'Seguimiento académico' },
      { days: 8, title: 'Reunión de seguimiento', context: 'Tutoría con la empresa' },
      { days: 15, title: 'Evaluación de desempeño', context: 'Revisión de mitad de período' },
      { days: 24, title: 'Presentación del informe final', context: 'Cierre de práctica' }
    ].map((event, index) => {
      const date = new Date(today);
      date.setDate(date.getDate() + event.days);
      return { _id: `agenda-demo-${index}`, cargo: event.title, contexto: event.context, fecha_fin: date.toISOString().slice(0, 10), demo: true };
    });
  })();
  const agendaItems=$derived(upcoming.length ? upcoming : sampleUpcoming);
  const quickModules=$derived(modules.filter(module=>!['TUTORES_ACADEMICOS','TUTORES_EMPRESARIALES','SEGURIDAD'].includes(module.modulo_codigo||module.codigo)).slice(0,4));
  const label=(key,row)=>{const m={ESTUDIANTES:['nombres','apellidos'],EMPRESAS:['nombre'],PROGRAMAS:['nombre'],PRACTICAS:['cargo'],SEGUIMIENTOS:['tipo']};if(key==='PRACTICAS'){const st=(data.ESTUDIANTES||[]).find(v=>v._id===row.estudiante_id);return st?`${st.nombres} ${st.apellidos}`:row.cargo;}return (m[key]||['nombre']).map(f=>row[f]).filter(Boolean).join(' ')};
</script>
<div class="dashboard-content"><div class="welcome-banner"><div class="welcome-copy"><span class="welcome-label"><Sparkles size={14}/> VISTA GENERAL</span><h2>Hola, {role||'bienvenido'} <span>👋</span></h2><p>Este es el estado actual de los procesos de prácticas.</p></div><div class="welcome-ornament"><div class="ornament-orbit orbit-one"></div><div class="ornament-orbit orbit-two"></div><span><BriefcaseBusiness size={27}/></span></div></div><div class="stats-grid"><StatCard label="Prácticas en curso" value={activePractices.length} hint="Seguimiento activo" icon={BriefcaseBusiness} accent="blue"/><StatCard label="Estudiantes" value={(data.ESTUDIANTES||[]).length} hint="En la plataforma" icon={GraduationCap} accent="violet"/><StatCard label="Empresas aliadas" value={(data.EMPRESAS||[]).length} hint="Organizaciones" icon={Building2} accent="amber"/><StatCard label="Módulos disponibles" value={modules.filter(module=>module.modulo_codigo!=='SEGURIDAD').length} hint="Según tu rol" icon={Activity} accent="green"/></div><div class="dashboard-grid"><section class="panel activity-panel"><div class="panel-heading"><div><span class="panel-kicker">ACTIVIDAD</span><h3>Prácticas recientes</h3><p>Un vistazo a las últimas asignaciones registradas</p></div><button class="text-button" onclick={()=>onnavigate('PRACTICAS')}>Ver todas <ArrowRight size={15}/></button></div>{#if (data.PRACTICAS||[]).length}<div class="activity-list">{#each [...(data.PRACTICAS||[])].slice(-5).reverse() as item (item._id)}{@const student=(data.ESTUDIANTES||[]).find(x=>x._id===item.estudiante_id)}{@const company=(data.EMPRESAS||[]).find(x=>x._id===item.empresa_id)}<button class="activity-row" onclick={()=>onnavigate('PRACTICAS')}><div class="activity-avatar">{student?.nombres?.charAt(0)||'P'}</div><div class="activity-main"><strong>{student?`${student.nombres} ${student.apellidos}`:item.cargo}</strong><span>{company?.nombre||'Organización asignada'} · {item.cargo}</span></div><StatusBadge value={item.estado}/></button>{/each}</div>{:else}<div class="dash-empty"><CircleCheck size={19}/><span>Los registros aparecerán aquí cuando la API esté disponible.</span></div>{/if}</section><section class="panel deadlines-panel"><div class="panel-heading"><div><span class="panel-kicker">{upcoming.length ? 'AGENDA' : 'AGENDA DE EJEMPLO'}</span><h3>Fechas próximas</h3><p>{upcoming.length ? 'Finalización de prácticas' : 'Fechas de referencia para organizar el seguimiento'}</p></div><span class="calendar-icon"><CalendarDays size={18}/></span></div><div class="deadline-list">{#each agendaItems as item (item._id)}{@const company=(data.EMPRESAS||[]).find(x=>x._id===item.empresa_id)}<div class:demo-deadline={item.demo} class="deadline-row"><span class="deadline-symbol">{#if item.demo}<CalendarDays size={15}/>{:else}<Clock3 size={16}/>{/if}</span><div class="deadline-main"><strong>{item.demo ? item.cargo : label('PRACTICAS',item)}</strong><span>{item.demo ? item.contexto : company?.nombre||item.cargo}</span></div>{#if item.demo}<span class="demo-deadline-label">Ejemplo</span>{/if}<span class="deadline-date">{new Date(`${item.fecha_fin}T12:00:00`).toLocaleDateString('es-CO',{day:'2-digit',month:'short'})}</span></div>{/each}</div></section></div><section class="quick-access"><div class="quick-heading"><span class="panel-kicker">ACCESO RÁPIDO</span><h3>Continúa con tu trabajo</h3></div><div class="quick-grid">{#each quickModules as module,i}{@const name=module.modulo_nombre||module.nombre}{@const code=module.modulo_codigo||module.codigo}<button class="quick-card" onclick={()=>onnavigate(code)}><span class="quick-number">0{i+1}</span><strong>{name}</strong><span>{module.modulo_descripcion||module.descripcion||'Gestiona este módulo'}</span><span class="quick-arrow"><ArrowRight size={15}/></span></button>{/each}</div></section></div>
